import{_ as s,o as a,c as t,a3 as o}from"./chunks/framework.0y4FC009.js";const u=JSON.parse('{"title":"How-to: index a multi-repo workspace","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/multi-repo.md","filePath":"how-to/multi-repo.md"}'),i={name:"how-to/multi-repo.md"};function n(r,e,d,p,l,c){return a(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="how-to-index-a-multi-repo-workspace" tabindex="-1">How-to: index a multi-repo workspace <a class="header-anchor" href="#how-to-index-a-multi-repo-workspace" aria-label="Permalink to &quot;How-to: index a multi-repo workspace&quot;">​</a></h1><p>For sibling checkouts — an org of repos that import each other — kuda keeps one index per repo <em>and</em> answers cross-repo questions over all of them.</p><h2 id="_1-declare-the-workspace" tabindex="-1">1. Declare the workspace <a class="header-anchor" href="#_1-declare-the-workspace" aria-label="Permalink to &quot;1. Declare the workspace&quot;">​</a></h2><p>Create <code>.kuda/workspace.yaml</code> in the checkout you run <code>kuda</code> from — either a repo&#39;s own <code>.kuda/</code> or a shared parent dir that holds the sibling repos:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">roots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kuda</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">mimus</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">../cli</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">../lsp</span></span></code></pre></div><p>Paths resolve relative to the directory that owns the <code>.kuda/</code> (the root <code>kuda</code> treats as cwd) — <em>not</em> the yaml&#39;s own directory. Roots listed there replace the single-repo default; add <code>.</code> if you want the home repo indexed too. One caveat: <code>--workspace</code> loads the config of the directory you run from and applies it to every root — sibling repos&#39; own <code>kuda.toml</code> files are not consulted, so keep per-root differences in the shared config or run <code>kuda sync</code> per repo instead.</p><p><code>[workspace] resolve_git_deps = true</code> in <code>kuda.toml</code> is the only workspace key the config file honors — it maps <code>git = &quot;…&quot;</code> manifest deps onto sibling checkouts (see step 4).</p><h2 id="_2-sync-all-roots" tabindex="-1">2. Sync all roots <a class="header-anchor" href="#_2-sync-all-roots" aria-label="Permalink to &quot;2. Sync all roots&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sync /home/you/GitHub/9aia/kuda</span></span>
<span class="line"><span>indexed 19 module(s) at af26b8c</span></span>
<span class="line"><span>sync /home/you/GitHub/9aia/mimus</span></span>
<span class="line"><span>indexed 15 module(s) at 323421e</span></span></code></pre></div><p>Each root gets its own <code>.kuda/</code> artifacts — the per-repo indexes stay independent and committable in their own repos.</p><h2 id="_3-query-across-the-set" tabindex="-1">3. Query across the set <a class="header-anchor" href="#_3-query-across-the-set" aria-label="Permalink to &quot;3. Query across the set&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kuda</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dependents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kuda-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span></span></code></pre></div><p>Edges found in <em>every</em> root&#39;s store are merged — so an import of <code>kuda-core</code> inside <code>mimus</code> shows up alongside internal users. That is the impact-analysis query that matters for a breaking change: &quot;who calls this, anywhere in the org&quot;.</p><h2 id="_4-git-dependency-edges" tabindex="-1">4. Git dependency edges <a class="header-anchor" href="#_4-git-dependency-edges" aria-label="Permalink to &quot;4. Git dependency edges&quot;">​</a></h2><p><code>resolve_git_deps = true</code> records the intent for the extractor tier that maps <code>git = &quot;…&quot;</code> manifest dependencies onto sibling checkouts — turning &quot;depends on github.com/x/y&quot; into &quot;depends on the sibling repo y&quot;. Until that lands, cross-repo edges come from module-name matching across the merged stores.</p><h2 id="current-limits" tabindex="-1">Current limits <a class="header-anchor" href="#current-limits" aria-label="Permalink to &quot;Current limits&quot;">​</a></h2><ul><li><code>find</code> and <code>refs</code> remain per-root; <code>dependents</code> is the merged query today.</li><li>Cards are generated per root — there is no aggregate workspace card yet. Compose one from <code>kuda map</code> output across roots.</li></ul>`,18)])])}const k=s(i,[["render",n]]);export{u as __pageData,k as default};
